// Continuously scrolling logo tape - the stack the build factory runs on.
// Transparent background with visible top/bottom borders; reuses the shared
// `.tape-track` animation (42s linear loop, no-ops under prefers-reduced-motion).
//
// Each entry is a clickable link to the vendor site (new tab) and carries an
// accessible name via aria-label + an SVG <title>. The track is doubled for a
// seamless loop; the second copy is decorative (aria-hidden, untabbable) so
// assistive tech and crawlers don't see duplicated links.
//
// Monochrome marks are sourced from Simple Icons (CC0). Testcontainers and
// Langfuse have no glyph in that set, so they render as text wordmarks.

interface Logo {
  name: string
  href: string
  viewBox?: string
  // Single-path mark. Rendered in the brand `color` when set, otherwise in
  // currentColor (the muted monochrome fallback).
  path?: string
  // Official brand colour for a single-path mark.
  color?: string
  // Multi-tone mark: paths keep their own brand fills. Used for logos that
  // only ship multi-colour (Testcontainers, Langfuse).
  colorPaths?: { d: string; fill: string }[]
}

